  key text NOT NULL CHECK (key ~ '^[a-zA-Z0-9_-]{1,64}$'),
  body jsonb NOT NULL,
  document_id uuid REFERENCES public.fp_documents(id),
  result jsonb,
  PRIMARY KEY (owner_id, key)
);
CREATE TABLE public.fp_document_audit (
  document_id uuid PRIMARY KEY REFERENCES public.fp_documents(id),
  owner_id uuid NOT NULL,
  request_key text NOT NULL,
  event text NOT NULL CHECK (event = 'created'),
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (owner_id, request_key) REFERENCES public.fp_document_requests(owner_id, key)
);
