CREATE TABLE public.fp_document_edits (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  document_id uuid NOT NULL REFERENCES public.fp_documents(id),
  owner_id uuid NOT NULL,
  event text NOT NULL CHECK (event = 'title_updated'),
  title text NOT NULL CHECK (length(title) BETWEEN 1 AND 120 AND title = btrim(title)),
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.fp_document_edits ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.fp_document_edits FROM PUBLIC, anon, authenticated;
CREATE FUNCTION public.fp_update_document_title(p_id uuid, p_title text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  actor uuid := auth.uid();
  doc public.fp_documents%ROWTYPE;
  title_value text := btrim(p_title);
BEGIN
  IF actor IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE = '42501'; END IF;
  IF title_value IS NULL OR length(title_value) NOT BETWEEN 1 AND 120 THEN
    RAISE EXCEPTION 'invalid_title' USING ERRCODE = '22023';
  END IF;
  UPDATE public.fp_documents SET title = title_value WHERE id = p_id AND owner_id = actor RETURNING * INTO doc;
  IF NOT FOUND THEN RAISE EXCEPTION 'not_found' USING ERRCODE = 'P0002'; END IF;
  INSERT INTO public.fp_document_edits(document_id,owner_id,event,title)
    VALUES(doc.id,actor,'title_updated',doc.title);
  RETURN jsonb_build_object('id',doc.id,'title',doc.title);
END;
$$;
REVOKE ALL ON FUNCTION public.fp_update_document_title(uuid,text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fp_update_document_title(uuid,text) TO authenticated;
NOTIFY pgrst, 'reload schema';
COMMIT;
