import { NextRequest, NextResponse } from 'next/server'
export async function proxy(request: NextRequest) {
  const changed = new Map<string, {name:string;value:string;options:CookieOptions}>()
  const cacheHeaders = new Headers()
  const client = createServerClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!, {
    cookies: {
      getAll: () => request.cookies.getAll(),
      setAll: (values, headers) => {
        values.forEach(cookie => { request.cookies.set(cookie.name,cookie.value); changed.set(cookie.name,cookie) })
        Object.entries(headers).forEach(([name,value]) => cacheHeaders.set(name,value))
      },
    },
  })
  // Read raw tokens once; only verified claims authorize the forwarded token.
  // Explicit JWT verification avoids a second refresh for short-lived sessions.
  const {data: {session}} = await client.auth.getSession()
  const forwarded = new Headers(request.headers)
  forwarded.delete('x-fp-access-token')
  if (session) {
    const {data,error} = await client.auth.getClaims(session.access_token)
    if (!error && data?.claims) forwarded.set('x-fp-access-token',session.access_token)
  }
  const response = NextResponse.next({ request: { headers: forwarded } })
  changed.forEach(({name,value,options}) => response.cookies.set(name,value,options))
  cacheHeaders.forEach((value,name) => response.headers.set(name,value))
  response.headers.set('Cache-Control', 'private, no-store, max-age=0, must-revalidate')
  return response
}
export const config = { matcher: ['/login', '/account/:path*', '/posts/:path*'] }
