import { createServerClient } from '@supabase/ssr'
import { createClient } from '@supabase/supabase-js'
import { cookies, headers } from 'next/headers'
import { redirect } from 'next/navigation'

// Cookie writes belong to Proxy and authentication Server Actions.
export async function supabase() {
  const jar = await cookies()
  return createServerClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!, {
    cookies: {
      getAll: () => jar.getAll(),
      setAll: values => values.forEach(({name,value,options}) => jar.set(name,value,options)),
    },
  })
}
export async function authenticated() {
  // Proxy removes any inbound value and forwards only a verified cookie token.
  // Verify against Auth again at command/read entry; no shared auth state.
  const token = (await headers()).get('x-fp-access-token')
  if (!token) redirect('/login')
  const client = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!, {
    auth: { persistSession: false, autoRefreshToken: false, detectSessionInUrl: false },
    global: {
      headers: { Authorization: `Bearer ${token}` },
      fetch: (input, init) => fetch(input, { ...init, cache: 'no-store' }),
    },
  })
  const {data,error} = await client.auth.getUser(token)
  if (error || !data.user) redirect('/login')
  return {client,user:data.user}
}
